import { Player, SDK } from "ysdk";
import {SafeWindowMessagesAdapter} from "../../events/SafeWindowMessagesAdapter";
import {IYandexSdkWindowMessages} from "./events";

interface IProps {
  isLogging?: boolean;
}

export class YandexSdkWrapper {
  protected sdk: SDK | undefined;
  protected player: Player | undefined;
  private readonly windowMessages = new SafeWindowMessagesAdapter<IYandexSdkWindowMessages>();
  private unSubGameApiPause?: () => void;
  private unSubGameApiResume?: () => void;

  constructor(private props: IProps = {}) {}

  async init() {
    try {
      if (typeof YaGames === "undefined" || YaGames == null) {
        this.log("YaGames unavailable");
        return;
      }
      if (this.sdk == null) {
        this.sdk = await YaGames.init();
      }
      this.initGameApiLifecycleEvents();
      await this.initPlayer();
    } catch (e) {
      this.log(e);
    }
  }

  getSDK(): SDK | undefined {
    return this.sdk;
  }

  getPlayer(): Player | undefined {
    return this.player;
  }

  /**
   * Сообщает платформе Yandex Games, что игра загрузилась и готова к взаимодействию.
   */
  signalGameReady(): void {
    try {
      this.sdk?.features?.LoadingAPI?.ready();
    } catch (e) {
      this.log(e);
    }
  }

  /**
   * Сообщает платформе Yandex Games, что игрок начал или возобновил игровой процесс.
   */
  signalGameplayStart(): void {
    try {
      this.sdk?.features?.GameplayAPI?.start?.();
    } catch (e) {
      this.log(e);
    }
  }

  /**
   * Сообщает платформе Yandex Games, что игровой процесс остановлен или поставлен на паузу.
   */
  signalGameplayStop(): void {
    try {
      this.sdk?.features?.GameplayAPI?.stop?.();
    } catch (e) {
      this.log(e);
    }
  }

  protected async initPlayer(): Promise<void> {
    try {
      this.player = await this.sdk?.getPlayer();
    } catch (error) {
      this.log(error);
    }
  }

  /** Пробрасывает события паузы Yandex SDK в общие window-сообщения игры. */
  private initGameApiLifecycleEvents(): void {
    const sdk = this.sdk;
    if (sdk == null || this.unSubGameApiPause != null || this.unSubGameApiResume != null) {
      return;
    }

    this.unSubGameApiPause = sdk.on("game_api_pause", () => {
      this.windowMessages.post(window, "pause_game", undefined, window.location.origin);
    });
    this.unSubGameApiResume = sdk.on("game_api_resume", () => {
      this.windowMessages.post(window, "resume_game", undefined, window.location.origin);
    });
  }

  protected log(...args: unknown[]) {
    if (this.props.isLogging !== true) return;
    console.log(...args);
  }
}
