import { makeAlign } from "@kvisaz/phaser-sugar";
import type { IBoundable } from "@kvisaz/phaser-sugar";
import { getSceneLocale, renderTemplateString } from "../../../../common";

interface IProps {
  scene: Phaser.Scene;
  anchor?: IBoundable;
}

const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
  fontFamily: "Russo One",
  fontStyle: "normal",
  fontSize: "36px",
  lineSpacing: 7,
  align: "center",
  color: "#FFFFFF",
  stroke: "rgba(10, 60, 130, 0.55)",
  strokeThickness: 5,
};

const textData = {
  localeMap: {
    en: "{{a}} / {{b}}",
    ru: "{{a}} / {{b}}",
  },
} as const;

/** Базовый информационный текст для сцены паука. */
export class BaseInfoText extends Phaser.GameObjects.Text {
  constructor(private readonly props: IProps) {
    super(props.scene, 0, 0, "", textStyle);

    const { scene } = props;
    scene.add.existing(this);

    this.setValue(0, 0);
  }

  /** Обновляет значение счетчика и возвращает компонент на якорь. */
  setValue(a: number, b: number): void {
    const locale = getSceneLocale(this.props.scene);
    const text = renderTemplateString(resolveLocaleText(locale), { a, b });
    this.setText(text);
    this.layout();
  }

  /** Выравнивает компонент относительно переданного anchor. */
  private layout(): void {
    const { anchor } = this.props;
    if (!anchor) {
      return;
    }

    makeAlign((align) => {
      align.anchor(anchor).centerX(this).bottomTo(this, 2);
    });
  }
}

/** Выбирает шаблон счетчика по локали сцены с fallback на поддерживаемые языки. */
function resolveLocaleText(locale?: string): string {
  const localeMap: Record<string, string> = textData.localeMap;
  return localeMap[String(locale || "")] ?? localeMap.en ?? localeMap.ru ?? "";
}
