import {GameServiceProvider} from "../../services";
import {
    ConsumableAmounts,
    InAppPurchaseId, IShopConfig,
    isInAppPurchaseId,
    isRewardPurchaseId,
    RewardPurchaseId,
} from "../../logic";

export type BonusShopRewardViewData = {
    id: RewardPurchaseId;
    consumables: ConsumableAmounts;
}

export type BonusShopBuyViewData = {
    id: InAppPurchaseId;
    consumables: ConsumableAmounts;
    priceString: string;
}

export type BonusShopViewData = {
    reward?: BonusShopRewardViewData;
    shopItems?: BonusShopBuyViewData[];
}

/**
 * прочитать gameConfig,
 * прочитать GameServiceProvider.get() данные магазина
 * вернуть доступные итемы в нужном формате и порядке,
 * priceString образуется из price + currency
 * **/
export function getBonusShopData(gameShopConfig: IShopConfig): BonusShopViewData {
    const gameService = GameServiceProvider.get();
    const shop = gameService.shop;
    const apiShopItems = shop?.apiShopItems ?? [];
    const rewardId = gameShopConfig.shopItemsOrdered.rewardItemIds[0];

    const reward = shop?.isRewardEnabled() && isRewardPurchaseId(rewardId)
        ? {
            id: rewardId,
            consumables: gameShopConfig.getShopItemData(rewardId).consumables,
        }
        : undefined;

    const shopItems = gameShopConfig.shopItemsOrdered.buyItemIds
        .map((id) => {
            if (!isInAppPurchaseId(id)) {
                return;
            }

            const apiShopItem = apiShopItems.find((item) => item.id === id);
            if (!apiShopItem) {
                return;
            }

            return {
                id,
                consumables: gameShopConfig.getShopItemData(id).consumables,
                priceString: `${apiShopItem.price} ${apiShopItem.currency}`,
            };
        })
        .filter((item): item is BonusShopBuyViewData => item != null);

    return {
        reward,
        shopItems,
    };
}
