import {deepCopy} from "../../mapAndObjects";
import {InstantDataService} from "./types";

interface IPlayerDataServiceProps<T extends object> {
    key: string;
    getDefaultData: () => T;
    localDataService: InstantDataService;
    getCloudService?: () => InstantDataService | undefined;
    saveDebounceMs: number;
}

/**
 * Инкапсулирует runtime-state и сохранение playerData без знания о конкретной модели игры.
 *  TODO добавить проверку сохраненного объекта на соответствие типу
 * */
export class PlayerDataService<T extends object> {
    private data: T;
    private saveTimer?: number;
    private lastSaveTimeMs?: number;

    constructor(private readonly props: IPlayerDataServiceProps<T>) {
        this.data = deepCopy(props.getDefaultData());
    }

    /** Загружает playerData из primary storage или дефолта. */
    load(): void {
        this.data = deepCopy(this.readSavedData() ?? this.props.getDefaultData());
    }

    /** Возвращает текущий playerData без ссылки на внутреннее состояние. */
    get(): T {
        return deepCopy(this.data);
    }

    /** Обновляет playerData частичным patch-объектом и планирует сохранение. */
    set(data: Partial<T>): void {
        this.data = deepCopy({
            ...this.data,
            ...data,
        });
        this.scheduleSave();
    }

    /** Сохраняет текущее состояние в доступные data-service кэши и их реализации. */
    async save(): Promise<void> {
        const playerData = deepCopy(this.data);

        this.props.localDataService.setData(this.props.key, playerData);
        const cloudService = this.props.getCloudService?.();
        if (cloudService) {
            await cloudService.setData(this.props.key, playerData);
        }
        this.lastSaveTimeMs = Date.now();
    }

    /** Немедленно сохраняет текущее состояние и дожидается облачной персистентности. */
    async flush(): Promise<void> {
        this.destroy();
        await this.save();
    }

    /** Сбрасывает отложенный таймер сохранения. */
    destroy(): void {
        if (this.saveTimer == null) {
            return;
        }

        clearTimeout(this.saveTimer);
        this.saveTimer = undefined;
    }

    /** Читает сохраненные данные с приоритетом облака над локальным кэшем. */
    private readSavedData(): T | undefined {
        return this.props.getCloudService?.()?.getData<T>(this.props.key)
            ?? this.props.localDataService.getData<T>(this.props.key);
    }

    /** Планирует сохранение с ограничением частоты записи. */
    private scheduleSave(): void {
        const now = Date.now();
        const {lastSaveTimeMs} = this;

        if (lastSaveTimeMs == null || now - lastSaveTimeMs >= this.props.saveDebounceMs) {
            this.destroy();
            this.save();
            return;
        }

        const safeDelayMs = Math.max(0, lastSaveTimeMs + this.props.saveDebounceMs - now);
        if (this.saveTimer != null) {
            clearTimeout(this.saveTimer);
        }
        this.saveTimer = window.setTimeout(() => {
            this.saveTimer = undefined;
            this.save();
        }, safeDelayMs);
    }

}
