import {Align} from "@kvisaz/phaser-sugar";
import {ViewElementBuilder} from "../../assets";
import {SpiderWrap} from "./components/SpiderWrap";
import {SpiderCardInfo} from "./components/SpiderCardInfo";
import {SpiderCollectButton, SpiderControls} from "./components/spider-ui";
import {SpiderGameSceneViewLogic} from "./logic";
import {defaultSpiderConfig, getSearchParam, SceneEvents} from "../../common";
import {GameServiceProvider} from "../../services";
import {SpiderGameScenes} from "../scenes";
import {IGameEvents} from '../events';
import {ButtonEvents} from "../auto_generated/utils/addButtonViewInteractivity";
import {gameScreenLayoutConfig} from "./config.layout";
import {ButtonSelectStyle} from '../auto_tuned/button-game-style';
import {addServiceBar} from '../shared/ServiceBar/addServiceBar';
import {gameConfig} from '../../config';

interface IProps {
    scene: Phaser.Scene;
}

export class SpiderGameSceneView {
    private readonly unSubs: Array<() => void> = [];
    private readonly gameLogic: SpiderGameSceneViewLogic;

    constructor(private readonly props: IProps) {
        const {scene} = props;
        const sceneEvents = new SceneEvents<IGameEvents>({scene});

        const builder = new ViewElementBuilder(scene);
        const playerData = GameServiceProvider.get().playerData.get();
        const spiderConfig = {
            ...defaultSpiderConfig,
            suitsMode: playerData.spiderSuitsMode,
        };
        this.gameLogic = new SpiderGameSceneViewLogic({scene, spiderConfig});
        this.unSubs.push(() => this.gameLogic.destroy());
        this.unSubs.push(() => sceneEvents.unSubscribeAll());
        const gameState = this.gameLogic.observable();


        const backButton = builder.buttonBack(() => {
            scene.scene.start(SpiderGameScenes.SpiderStart);
        });
        Align.setLeftTop(backButton, gameScreenLayoutConfig.buttonBack.left, gameScreenLayoutConfig.buttonBack.top);
        this.unSubs.push(() => backButton.destroy());

        const {info} = gameScreenLayoutConfig;
        if (gameConfig.gameDebugNumbersEnabled) {
            const cardInfo = new SpiderCardInfo({
                scene,
                gameState,
            });
            Align.setLeftTop(cardInfo, info.left, info.top);
            this.unSubs.push(() => cardInfo.destroy());
        }

        const controls = new SpiderControls({
            scene,
            gameState,
        });
        this.unSubs.push(() => controls.destroy());

        const collectButton = new SpiderCollectButton({
            scene,
            gameState,
        });
        Align.setLeftTop(collectButton, gameScreenLayoutConfig.buttonCollect.left, gameScreenLayoutConfig.buttonCollect.top);
        this.unSubs.push(() => collectButton.destroy());

        const spiderWrap = new SpiderWrap({
            scene,
        });
        this.unSubs.push(() => spiderWrap.destroy());

        this.unSubs.push(
            sceneEvents.on("uiModeSelectClick", () => {
                scene.scene.start(SpiderGameScenes.SpiderStart);
            }),
            sceneEvents.on("onGameOverNewGameClick", () => {
                this.restartGameAfterOptionalCommonAd(scene, sceneEvents);
            }),
            sceneEvents.on("onGameOverExitClick", () => {
                scene.scene.start(SpiderGameScenes.SpiderStart);
            }),
        );

        this.addGameStyleButton(scene, sceneEvents);
        /** показываем тестовую кнопку если разрешен конфиг и есть параметр **/
        if(gameConfig.test?.gameOverButton && getSearchParam('gameOver')){
            this.addTestGameOverButton(scene, sceneEvents);
        }
        /** настройки и магазин **/
        addServiceBar({builder, sceneEvents, scene});


        this.gameLogic.startNewGame({shuffleDeck: true, grantEntryConsumables: true});
    }

    destroy() {
        this.unSubs.forEach((u) => u());
        this.unSubs.length = 0;
    }


    private addGameStyleButton(scene: Phaser.Scene, sceneEvents: SceneEvents<IGameEvents>): void {
        const button = new ButtonSelectStyle({scene, width: gameScreenLayoutConfig.buttonStyle.width});
        scene.add.existing(button);
        Align.setLeftTop(button, gameScreenLayoutConfig.buttonStyle.left, gameScreenLayoutConfig.buttonStyle.top);
        this.unSubs.push(() => button.destroy());

        const onButtonClick = ({gameObjectName}: { gameObjectName: string }) => {
            if (gameObjectName !== button.name) {
                return;
            }
            sceneEvents.emit("onSelectStyleButtonClick");
        };

        scene.events.on(ButtonEvents.onClick, onButtonClick);
        this.unSubs.push(() => scene.events.off(ButtonEvents.onClick, onButtonClick));
    }

    /** Добавляет временную кнопку для ручной проверки события открытия GameOver-диалога. */
    private addTestGameOverButton(scene: Phaser.Scene, sceneEvents: SceneEvents<IGameEvents>): void {
        const builder = new ViewElementBuilder(scene);
        const {left, top, width, height} = gameScreenLayoutConfig.buttonTestGameOver;
        const button = builder.buttonPrimary("Тест Gameover", () => {
            sceneEvents.emit("onGameOverDialogRequest");
        }, {
            width,
            height,
            fontSizePx: 24
        });

        scene.add.existing(button);
        Align.setLeftTop(button, left, top);
        this.unSubs.push(() => button.destroy());
    }

    /** Запрашивает common-рекламу у overlay manager и перезапускает игру после результата. */
    private restartGameAfterOptionalCommonAd(scene: Phaser.Scene, sceneEvents: SceneEvents<IGameEvents>): void {
        sceneEvents.once("gameCommonAdClosed", () => {
            this.restartGameScene(scene);
        });
        sceneEvents.emit("requestCommonAd");
    }

    /** Перезапускает SpiderGame через переход на эту же сцену. */
    private restartGameScene(scene: Phaser.Scene): void {
        scene.scene.start(SpiderGameScenes.SpiderGame);
    }
}
