import packageInfo from "../package.json";
import { gameConfig, phaserGameConfig } from "./config";
import {getDefaultPlayerData} from "./config.default";
import { gameScenes } from "./scenes";
import { getLocalizedText } from "./assets";
import { HtmlRoot } from "./common/html";
import { GameServiceProvider } from "./services";
import type {ServiceConfig} from "./services";

console.log(`${packageInfo.name} ${packageInfo.version} starting...`);
console.log(`${packageInfo.description}`);
console.log("...................");
console.log("test 02");

HtmlRoot.root = document.getElementById("game")!;

const serviceConfig: ServiceConfig = {
  gameId: gameConfig.gameId,
  commonAdCooldownMs: gameConfig.ads.cooldowns.commonMs,
  rewardAdCooldownMs: gameConfig.ads.cooldowns.rewardMs,
  saveDebounceMs: gameConfig.dataServiceOptions.saveDebounceMs,
  getDefaultPlayerData,
  shopItemsOrdered: gameConfig.shop.shopItemsOrdered,
  addShopItemToPlayerData: gameConfig.shop.addShopItemToState,
};

GameServiceProvider.reset({
  serviceConfig,
});

new Phaser.Game({
  ...phaserGameConfig,
  scene: [...gameScenes],
});
/* ---------------------------------------------------------
 *  Отключаем контекстное меню браузера
 * --------------------------------------------------------- */
document.body.addEventListener("contextmenu", (e) => e.preventDefault());

/* ---------------------------------------------------------
 *  Включаем локализованный title
 * --------------------------------------------------------- */
const titleText = getLocalizedText("start.logo.title");
const subTitleText = getLocalizedText("start.logo.subtitle");
document.title = `${titleText} - ${subTitleText}`;
