import {SceneEvents} from "../../../common";
import {
    ConsumableAmounts,
    ConsumableType,
    getPlayerConsumables,
    makePlayerConsumablesPatch,
} from "../../../logic";
import {GameServiceProvider} from "../../../services";
import {IGameEvents} from "../../events";

/** Централизует изменение баланса расходников и единственный emit обновления UI. */
export class ConsumablesFlow {
    private readonly sceneEvents: SceneEvents<IGameEvents>;
    private readonly unSubs: Array<() => void> = [];

    constructor(scene: Phaser.Scene) {
        this.sceneEvents = new SceneEvents<IGameEvents>({scene});
        const onSceneShutdown = () => this.destroy();
        this.unSubs.push(
            this.sceneEvents.on("grantConsumables", ({consumables}) => this.grant(consumables)),
            this.sceneEvents.on("spendConsumable", ({type}) => this.spend(type)),
            this.sceneEvents.on("syncConsumables", () => this.sync()),
            () => scene.events.off(Phaser.Scenes.Events.SHUTDOWN, onSceneShutdown),
        );
        scene.events.once(Phaser.Scenes.Events.SHUTDOWN, onSceneShutdown);
    }

    /** Снимает подписки flow со сцены. */
    destroy(): void {
        this.unSubs.forEach((unSub) => unSub());
        this.unSubs.length = 0;
        this.sceneEvents.unSubscribeAll();
    }

    /** Выдает пакет только по тем расходникам, которые сейчас на нуле. */
    private grant(consumables: ConsumableAmounts): void {
        const current = this.get();
        this.apply({
            [ConsumableType.UNDO]: current[ConsumableType.UNDO] > 0
                ? current[ConsumableType.UNDO]
                : consumables[ConsumableType.UNDO],
            [ConsumableType.HINT]: current[ConsumableType.HINT] > 0
                ? current[ConsumableType.HINT]
                : consumables[ConsumableType.HINT],
            [ConsumableType.MAGIC]: current[ConsumableType.MAGIC] > 0
                ? current[ConsumableType.MAGIC]
                : consumables[ConsumableType.MAGIC],
        });
    }

    /** Списывает один расходник выбранного типа, если он есть. */
    private spend(type: ConsumableType): void {
        const current = this.get();
        if (current[type] <= 0) {
            return;
        }

        this.apply({
            ...current,
            [type]: current[type] - 1,
        });
    }

    /** Публикует обновление после внешней записи расходников, например покупки в shop service. */
    private sync(): void {
        this.sceneEvents.emit("gameConsumablesUpdated");
    }

    /** Читает текущий баланс расходников из player data. */
    private get(): ConsumableAmounts {
        return getPlayerConsumables(GameServiceProvider.get().playerData.get());
    }

    /** Сохраняет новый баланс и публикует единое событие обновления расходников. */
    private apply(consumables: ConsumableAmounts): void {
        GameServiceProvider.get().playerData.set(makePlayerConsumablesPatch(consumables));
        this.sync();
    }
}
