import type {AlignObject, IBoundable} from "@kvisaz/phaser-sugar";
import {Align, arrayAlign} from "@kvisaz/phaser-sugar";
import {cardLayoutConfig} from "../../config.layout";

interface ISpiderSourceDeckLayoutStrategyProps {
    items: AlignObject[];
    inputZone: IBoundable;
    stockDealCardCount: number;
    stockCardsAfterInitialDeal: number;
}

/** Раскладывает stock-колоду порциями по раздачам, не меняя порядок карт в стеке. */
export function spiderSourceDeckLayoutStrategy({
                                                   items,
                                                   inputZone,
                                                   stockDealCardCount,
                                                   stockCardsAfterInitialDeal,
                                               }: ISpiderSourceDeckLayoutStrategyProps): void {
    if (items.length < 1 || stockDealCardCount < 1) {
        return;
    }

    const initialDealStartIndex = items.length > stockCardsAfterInitialDeal
        ? stockCardsAfterInitialDeal
        : items.length;
    const initialDealPortionIndex = Math.floor(initialDealStartIndex / stockDealCardCount);
    const {offsetY, offsetX} = cardLayoutConfig.sourceDeck;
    const align = new Align(inputZone);

    items.forEach((item, index) => {
        const portionIndex = index < initialDealStartIndex
            ? Math.floor(index / stockDealCardCount)
            : initialDealPortionIndex;

        align.center(item, -portionIndex * offsetX, -portionIndex * offsetY);
    });

    const deck = arrayAlign.alignObject(items);
    align.anchor(inputZone).bottomIn(deck).leftIn(deck);
}
