import {makeAlign} from "@kvisaz/phaser-sugar";
import {SceneEvents} from "../../../common";
import {ISceneDialogHandle, openSceneDialog} from "../../../common/game-core";
import {GameServiceProvider} from "../../../services";
import {IGameCommonAdCloseResult, IGameEvents, IGameRewardPurchaseCloseResult} from "../../events";
import {AdRunResult} from "./types";

interface ISpiderAdOverlayManagerProps {
    scene: Phaser.Scene;
}

const AD_OVERLAY_TIMEOUT_MS = 120_000;

/** Управляет рекламным overlay внутри игровой сцены без запуска отдельных Phaser ad-сцен. */
export class SpiderAdOverlayManager {
    private readonly unSubs: Array<() => void> = [];
    private readonly sceneEvents: SceneEvents<IGameEvents>;
    private dialog?: ISceneDialogHandle;
    private isAdInProgress = false;
    private isSoundMutedByAd = false;
    private timeoutEvent?: Phaser.Time.TimerEvent;

    constructor(private readonly props: ISpiderAdOverlayManagerProps) {
        this.sceneEvents = new SceneEvents<IGameEvents>({scene: props.scene});
        this.unSubs.push(
            this.sceneEvents.on("requestCommonAd", () => this.runAsync(() => this.showCommonAdFlow())),
            this.sceneEvents.on("requestRewardPurchase", ({rewardItemId}) => {
                this.runAsync(() => this.purchaseRewardFlow(rewardItemId));
            }),
        );

        const onSceneShutdown = () => this.destroy();
        props.scene.events.once(Phaser.Scenes.Events.SHUTDOWN, onSceneShutdown);
        this.unSubs.push(() => props.scene.events.off(Phaser.Scenes.Events.SHUTDOWN, onSceneShutdown));
    }

    /** Очищает overlay, таймеры и подписки при закрытии игровой сцены. */
    destroy(): void {
        this.clearAdState();
        this.unSubs.forEach((unSub) => unSub());
        this.unSubs.length = 0;
    }

    /** Сбрасывает runtime-состояние рекламы без изменения подписок manager-а. */
    private clearAdState(): void {
        this.dialog?.destroy();
        this.dialog = undefined;
        this.timeoutEvent?.remove(false);
        this.timeoutEvent = undefined;
        this.restoreSceneSoundFromSettings();
        this.isAdInProgress = false;
    }

    /** Запускает async-flow из sync event-listener и не выпускает ошибки в unhandled rejection. */
    private runAsync(handler: () => Promise<void>): void {
        handler().catch((error) => {
            console.warn("ad overlay async handler failed", error);
            this.clearAdState();
        });
    }

    /** Показывает обычную рекламу и всегда завершает flow событием `gameCommonAdClosed`.
     * Асинхронно выполняет common ad flow и переводит любую ошибку в событие закрытия рекламы. */
    private async showCommonAdFlow(): Promise<void> {
        try {
            const gameService = GameServiceProvider.get();
            if (!gameService.isFullAdEnabled) {
                this.sceneEvents.emit("gameCommonAdClosed", {
                    wasShown: false,
                    error: "common ad not available",
                });
                return;
            }

            const result = await this.runWithAdOverlay<IGameCommonAdCloseResult>({
                label: "Реклама",
                run: (finish) => gameService.showCommonAd(finish),
                fallbackResult: {
                    wasShown: false,
                    error: "common ad timeout",
                },
            });

            this.sceneEvents.emit("gameCommonAdClosed", result);
        } catch (error) {
            this.clearAdState();
            this.sceneEvents.emit("gameCommonAdClosed", {
                wasShown: false,
                error: String(error),
            });
        }
    }

    /** Запускает reward-покупку магазина под общим рекламным overlay.
     * Асинхронно выполняет rewarded flow и переводит любую ошибку в событие закрытия рекламы. */
    private async purchaseRewardFlow(rewardItemId: string): Promise<void> {
        try {
            const shop = GameServiceProvider.get().shop;
            if (shop == null || !shop.isRewardEnabled()) {
                this.sceneEvents.emit("gameRewardPurchaseClosed", {
                    rewardItemId,
                    error: "reward ad not available",
                });
                return;
            }

            const result = await this.runWithAdOverlay<IGameRewardPurchaseCloseResult>({
                label: "Реклама с наградой",
                run: (finish) => this.runRewardPurchase(rewardItemId, finish),
                fallbackResult: {
                    rewardItemId,
                    error: "reward ad timeout",
                },
                isTimeoutEnabled: false,
            });

            this.sceneEvents.emit("gameRewardPurchaseClosed", result);

            if (result.error == null) {
                this.sceneEvents.emit("syncConsumables");
            }
        } catch (error) {
            this.clearAdState();
            this.sceneEvents.emit("gameRewardPurchaseClosed", {
                rewardItemId,
                error: String(error),
            });
        }
    }

    /** Выполняет покупку reward-пакета и всегда завершает callback штатным результатом. */
    private async runRewardPurchase(
        rewardItemId: string,
        finish: (result: IGameRewardPurchaseCloseResult) => void,
    ): Promise<void> {
        try {
            const shop = GameServiceProvider.get().shop;
            if (shop == null) {
                finish({
                    rewardItemId,
                    error: "shop not available",
                });
                return;
            }

            const result = await shop.purchaseReward(rewardItemId);
            finish({
                rewardItemId,
                purchaseId: result.purchaseId,
                error: result.error,
            });
        } catch (error) {
            finish({
                rewardItemId,
                error: String(error),
            });
        }
    }

    /** Оборачивает показ рекламы в modal-overlay, временный mute и гарантированное закрытие. */
    private runWithAdOverlay<T extends AdRunResult>(props: {
        label: string;
        run: (finish: (result: T) => void) => void;
        fallbackResult: T;
        isTimeoutEnabled?: boolean;
    }): Promise<T> {
        if (this.isAdInProgress) {
            return Promise.resolve({
                ...props.fallbackResult,
                error: "ad already in progress",
            } as T);
        }

        this.isAdInProgress = true;
        this.openOverlay(props.label);
        this.muteSceneSound();

        return new Promise<T>((resolve) => {
            let isFinished = false;
            const finish = (result: T) => {
                if (isFinished) {
                    return;
                }

                isFinished = true;
                this.closeOverlay();
                this.restoreSceneSoundFromSettings();
                this.timeoutEvent?.remove(false);
                this.timeoutEvent = undefined;
                this.isAdInProgress = false;
                resolve(result);
            };

            if (props.isTimeoutEnabled !== false) {
                /**
                 * Страховка против зависания overlay, если внешний ad SDK не вернул ни close, ни error.
                 * Для reward-flow таймер отключаем, потому что покупка может позже начислить награду в сервисе.
                 */
                this.timeoutEvent = this.props.scene.time.delayedCall(AD_OVERLAY_TIMEOUT_MS, () => {
                    finish(props.fallbackResult);
                });
            }

            try {
                props.run(finish);
            } catch (error) {
                finish({
                    ...props.fallbackResult,
                    error: String(error),
                } as T);
            }
        });
    }

    /** Открывает простой modal-overlay с подписью текущего рекламного flow. */
    private openOverlay(label: string): void {
        this.closeOverlay();
        this.dialog = openSceneDialog({
            scene: this.props.scene,
            isCloseOnOverlayClick: false,
            overlayAlpha: 0.64,
            createContent: ({scene}) => this.createOverlayContent(scene, label),
            onClose: () => {
                this.dialog = undefined;
            },
        });
    }

    /** Создает компактный контент overlay без дополнительных ассетов. */
    private createOverlayContent(scene: Phaser.Scene, label: string): Phaser.GameObjects.Container {
        const bg = new Phaser.GameObjects.Rectangle(scene, 0, 0, 560, 170, 0x111111, 0.9)
            .setStrokeStyle(2, 0xffffff, 0.35);
        const title = new Phaser.GameObjects.Text(scene, 0, 0, label, {
            fontFamily: "\"Russo One\", Roboto, Verdana, sans-serif",
            fontSize: "38px",
            color: "#ffffff",
            align: "center",
        }).setOrigin(0.5);
        const subtitle = new Phaser.GameObjects.Text(scene, 0, 0, "Пожалуйста, подождите", {
            fontFamily: "Roboto, Verdana, sans-serif",
            fontSize: "26px",
            color: "#ffffff",
            align: "center",
        }).setOrigin(0.5).setAlpha(0.82);
        const content = new Phaser.GameObjects.Container(scene, 0, 0, [bg, title, subtitle]);
        content.setSize(bg.width, bg.height);

        /** Верстаем текст внутри фона через реальные размеры прямоугольника, чтобы CommonModal корректно центрировал контейнер. */
        makeAlign((align) => {
            align
                .anchor(bg)
                .centerX(title)
                .centerY(title, -24)
                .centerX(subtitle)
                .centerY(subtitle, 34);
        });

        return content;
    }

    /** Закрывает modal-overlay без влияния на результат рекламы. */
    private closeOverlay(): void {
        this.dialog?.close();
        this.dialog = undefined;
    }

    /** Временно мутит всю сцену на время показа рекламы. */
    private muteSceneSound(): void {
        this.props.scene.sound.mute = true;
        this.isSoundMutedByAd = true;
    }

    /** Восстанавливает звук только если он разрешен текущими настройками игрока. */
    private restoreSceneSoundFromSettings(): void {
        if (!this.isSoundMutedByAd) {
            return;
        }

        this.isSoundMutedByAd = false;
        const playerData = GameServiceProvider.get().playerData.get();
        this.props.scene.sound.mute = !playerData.isSoundOn;
    }
}
