import {assetsViewsAutoAssets} from "../auto_generated/assets-views-assets";
import {getSceneLocale, makeContainerInteractive} from '../../common';
import {center} from './utils.tuned';

const textButtonGameStyle = {
    name: "textButtonGameStyle",
    x: 515,
    y: 5842,
    width: 113,
    height: 38,
    localeMap: {
        en: "STYLE",
        ru: "СТИЛЬ",
    },
    style: {
        fontFamily: "\"Russo One\", Roboto, Verdana, sans-serif",
        fontSize: 30,
        color: "#ffffff",
        align: "center",
        stroke: "#000000",
        strokeThickness: 1,
    },
};

const btGameStyleData = {
    name: "buttonGameStyle",
    button: true,
    width: 124,
    height: 60,
    children: {
        "ui.button.yellow.height82.nine.30": {
            asset: assetsViewsAutoAssets.uiButtonYellowHeight82Nine30,
            x: 0,
            y: 0,
            width: 124,
            height: 60,
        },
        textButtonGameStyle: {
            type: "text",
            text: textButtonGameStyle,
            x: 7,
            y: 11,
            width: 113,
            height: 38,
        },
    },
};

interface IProps {
    scene: Phaser.Scene;
    width?: number;
    height?: number;
    fontSize?: string;
}

/** Создает кнопку выбора стиля игры с настраиваемым размером фона. */
export class ButtonSelectStyle extends Phaser.GameObjects.Container {
    constructor(protected props: IProps) {
        super(props.scene, 0, 0);
        const {scene} = props;
        const {asset: bgAsset } = btGameStyleData.children["ui.button.yellow.height82.nine.30"];
        const bg = new Phaser.GameObjects.NineSlice(scene, 0, 0, bgAsset.url, bgAsset.frameName,
            props.width ?? bgAsset.width,
            props.height ?? bgAsset.height,
            bgAsset.ninePadding,
            bgAsset.ninePadding,
            bgAsset.ninePadding,
            bgAsset.ninePadding
        )
        const textData =  btGameStyleData.children.textButtonGameStyle;

        const locale = (getSceneLocale(scene) ?? 'ru') as 'en' | 'ru';
        const label = textData.text.localeMap[locale];
        const textStyle = {
            ...textData.text.style,
            fontSize: props.fontSize ?? textData.text.style.fontSize
        }
        const text = new Phaser.GameObjects.Text(scene, 0, 0, label, textStyle);
        center(bg, text);
        this.add([bg, text]);

        // создает эффект кнопки
        this.setData("button", true);
        this.name = btGameStyleData.name;
        makeContainerInteractive(this);
    }
}
